// catalog-rules/strings.js - UI strings of Catalog Rules (schema and rules pages) in the 7 UI languages.
//
// Structure: one flat object per language, keys namespaced with this app's prefix ('cr.') so addDicts() can merge
// every app's dictionaries into one table without collisions. Placeholders are {name}, filled by t(key, { name });
// a translation must keep every placeholder of the English line. English is the reference: a key missing in another
// language falls back to it (ui/i18n.js), so a new key only needs English to ship. Values that are objects
// ({ one, few, many, other }) are plural forms, picked from the {n} variable by pluralCat() in ui/i18n.js.
// Imported for its side effect (registration at module load), before any t() call of the app runs.
import { addDicts } from '../ui/i18n.js';

